import json, sys
d = json.load(open(sys.argv[1]))
order = ['strip_l', 'strip_r', 'top', 'floor', 'props', 'rug', 'board', 'card', 'eagle', 'cases']
by = {r['id']: r for r in d['regions']}
o = ["""/**
 * GENERATED by scripts/shelf-trace (do not edit by hand).
 *
 * The approved home-page picture traced into vector layers. Every colour is a
 * tone name (see `Tones` in scene-trace.tsx) so palettes recolour the art; the
 * eagle alone uses literal colours. Path data is in 1/TRACE_SCALE scene units,
 * relative line segments, even-odd fill.
 */
export const TRACE_SCALE = 3;

export interface TraceLayer {
  readonly tone: string;
  readonly d: string;
}

export interface TraceRegion {
  readonly id: string;
  /** x, y, width, height in scene units */
  readonly box: readonly [number, number, number, number];
  /** tone filling the whole box under the layers, if any */
  readonly base?: string;
  readonly layers: readonly TraceLayer[];
}

export const TRACE: readonly TraceRegion[] = ["""]
for i in order:
    if i not in by: continue
    r = by[i]
    o.append("  {")
    o.append("    id: '%s'," % i)
    o.append("    box: [%s]," % ', '.join(str(v) for v in r['box']))
    if r['base']: o.append("    base: '%s'," % r['base'])
    o.append("    layers: [")
    for k, p in r['layers']:
        o.append("      {")
        o.append("        tone: '%s'," % k)
        o.append("        d: '%s'," % p)
        o.append("      },")
    o.append("    ],")
    o.append("  },")
o.append("];")
open(sys.argv[2], 'w').write('\n'.join(o) + '\n')
